namespace Fanex.Web.Statistic.Services
{
    using System.Linq;
    using System.Web;
    using Fanex.Common;
    using Fanex.Web.Statistic.Configurations;
    using Fanex.Web.Statistic.DataAccess;

    /// <summary>
    /// TODO: Update summary.
    /// </summary>
    public class FunctionUsageStatisticService : IFunctionUsageStatisticService
    {
        private IFunctionUsageStatisticDataAccess _functionUsageStatisticDataAccess;
        
        public FunctionUsageStatisticService()
        {
            _functionUsageStatisticDataAccess = new FunctionUsageStatisticDataAccess();
        }

        /// <summary>
        /// Insert New Statistic.
        /// </summary>
        /// <param name="userRequest">User request.</param>
        /// <param name="isDirectUpdate">Is Direct Update.</param>
        public void InsertNewStatistic(HttpRequest userRequest, bool isDirectUpdate = false)
        {
            var functionStatisticSection = FunctionStatisticSection.Instance;
            if (functionStatisticSection == null ||
                functionStatisticSection.Functions == null ||
                functionStatisticSection.Functions.Count <= 0)
            {
                return;
            }

            var requestPath = userRequest.AppRelativeCurrentExecutionFilePath;
            var functionSettings =
                from setting in
                    functionStatisticSection.Functions.Cast<FunctionElement>().Where(setting => 
                        string.Compare(setting.Path, requestPath, true) == 0 && 
                        setting.IsDirectUpdate == isDirectUpdate)
                select setting;

            if (functionSettings == null || functionSettings.Count() <= 0)
            {
                return;
            }

            var custId = Converter.ToInt(userRequest["customerloginid"]);
            var roleId = Converter.ToInt(userRequest["roleid"]);
            var serverId = functionStatisticSection.SiteId;
            var deviceInfo = GetUserDeviceInfo(userRequest);            
            var functionSettingDetail = functionSettings.FirstOrDefault();
            var actionId = functionSettingDetail.ActionId;

            if (custId == 0 || roleId == 0 || serverId == 0)
            {
                return;
            }

            if (functionSettingDetail.Params != null && functionSettingDetail.Params.Count > 0)
            {
                var actionDetail = from action in
                                       functionSettingDetail.Params.Cast<ParamElement>().Where(action => string.Compare(action.Value, Converter.ToString2(userRequest["type"]), true) == 0)
                                   select action;

                if (actionDetail == null || actionDetail.Count() <= 0)
                {
                    return;
                }

                actionId = actionDetail.FirstOrDefault().ActionId;
            }

            _functionUsageStatisticDataAccess.InsertNewStatistic(custId, roleId, actionId, serverId, deviceInfo);
        }

        /// <summary>
        /// Get User Device Info.
        /// </summary>
        /// <param name="userRequest">User request.</param>
        /// <returns>Return device info.</returns>
        private string GetUserDeviceInfo(HttpRequest userRequest)
        {
            var deviceInfo = "Platform: {0}/Browser: {1} {2}";

            if (userRequest.Browser.IsMobileDevice)
           {
                return string.Format(
                    deviceInfo, 
                    userRequest.Browser.MobileDeviceModel,
                    userRequest.Browser.Browser,
                    userRequest.Browser.MajorVersion);
            }
            else
            {
                return string.Format(
                    deviceInfo,
                    GetPlatform(userRequest),
                    userRequest.UserAgent.Contains("Chrome") ? "Chrome" : userRequest.Browser.Browser,
                    userRequest.Browser.Version);
            }
        }

        /// <summary>
        /// Gets the platform.
        /// </summary>
        /// <param name="userRequest">User request.</param>
        /// <returns>System String.</returns>
        private string GetPlatform(HttpRequest userRequest)
        {
            //// Create a list of all platform
            string[] platform = new[] 
            { 
                "Windows 3", 
                "Win16", 
                "Windows 95", 
                "Win95", 
                "Windows 98",
                "Win98",
                "Windows 2000",
                "Windows XP",
                "Windows Server 2003",
                "Windows Vista",
                "Windows NT",
                "WinNT", 
                "Windows ME",
                "Open BSD", 
                "OpenBSD",
                "Sun OS",
                "SunOS",
                "Linux", 
                "Mac OS", 
                "Mac_PowerPC",
                "Macintosh",
                "QNX", 
                "QNX",
                "BeOS", 
                "BeOS", 
                "OS/2", 
                "OS/2",
                "Android"
            };

            //// Loop through each item in the list created above and check if the header contains that text.
            foreach (string s in platform)
            {
                if (userRequest.ServerVariables["HTTP_USER_AGENT"].ToLower().Contains(s.ToLower()))
                {
                    return s;
                }
            }

            return "Unknown";
        }
    }
}